/** The wall. Generated by prep/emit.mjs from the capture run — never edited
 *  by hand, so what was checked on the verification sheets is what renders.
 *
 *  Every sentence below came out of a template filled with a measurement. No
 *  model wrote any of it, and no line says what anyone intended: nobody outside
 *  these companies knows that, and a page that guesses at motive is a page that
 *  can be wrong about a named business.
 *
 *  `pins` are percentages of the capture, taken from each element's own
 *  bounding box in the SAME page visit that produced the image beside it. They
 *  are the element's top-left corner, so a pin sits next to what it names
 *  rather than covering it.
 *
 *  Captured 2026-09-11, Chromium 1280x900 at 2x, locale en-GB, from
 *  Switzerland, each in a clean browser profile. Consent dialogs vary by country
 *  and change often; these are what one browser saw on one day. */

export type Pin = { n: number; x: number; y: number; note: string };
export type Fact = { label: string; value: string; heavy?: boolean };

export type Exhibit = {
  slug: string;
  site: string;
  url: string;
  /** the pattern family, not a verdict */
  family: string;
  shot: string;
  stage: string;
  headline: string;
  standfirst: string;
  pins: Pin[];
  facts: Fact[];
  /** what this exhibit does NOT claim */
  limit: string;
  /** the dialog's own words, where a claim quotes them */
  quote?: string;
};

export const CAPTURED = "2026-09-11";
export const SITES_VISITED = 90;

