export const FAMILIES: string[] = [...new Set(EXHIBITS.map((e) => e.family))];
export const SITES: string[] = [...new Set(EXHIBITS.map((e) => e.site))];

/** The headline figure, summed from the exhibits rather than typed. */
export const COMPANIES_NAMED = EXHIBITS.filter((e) => e.family === "The size of the yes")
  .map((e) => Number(String(e.facts[0].value).replace(/\D/g, "")))
  .reduce((a, b) => a + b, 0);

export const BY_FAMILY: { family: string; items: Exhibit[] }[] = FAMILIES.map((family) => ({
  family,
  items: EXHIBITS.filter((e) => e.family === family),
}));

/** Words that assert a state of mind. qa/attack.mjs fails the build on any of
 *  them rather than trusting a template to stay clean. */
export const BANNED_INTENT = [
  "trick", "deceive", "dupe", "manipulat", "sneaky", "shady", "evil", "malicious",
  "designed to", "intended to", "wants you to", "want you to", "on purpose",
  "deliberately", "cynical", "predatory", "scam", "mislead", "dishonest",
  "greedy", "exploit", "prey on", "dark pattern", "hopes you",
];
